import numpy as np
DESCRIPTION="Attention-only net, decision = argmax of the last position's readout. embed: position p holds WE[x_p]+WP[p]. layer0: score E A0 E^T (A0=QK^T/sqrt8), softmax over the 6 keys, residual r=E+a(E P0) (P0=V O). layer1 reads only query position 5: score (r5 A1).r_j, softmax a1, logits = r5 WU + sum_j a1_j (r_j M), M=V O U (rank 3). Classes: 1 = 2-cycle, 0/2/3 = fixed-point structure. All matrices are rounded to 2-3 significant digits (scale 1e-2 or 1e-3)."
WE=np.array([[-610,-106,-1610,376,1113,-182,-158,20],[-69,-266,-247,275,437,199,-237,248],[955,-1091,-315,-827,404,419,187,952],[-180,2180,464,-352,449,1144,-83,216],[-1062,92,1343,285,441,-197,402,-92],[-2012,-40,-720,-1303,331,15,907,290]])*1e-3
WP=np.array([[-458,1152,-34,737,324,-1222,-619,1244],[541,-745,-1070,-133,-1218,509,1114,-264],[-665,-213,56,215,-544,868,-250,3578],[-527,-845,324,-80,358,740,-1665,-473],[-361,-212,-509,-4377,272,-551,-396,-758],[10,716,661,459,2620,317,1165,-58]])*1e-3
A0=np.array([[-52,66,-64,80,-308,118,102,117],[-107,-92,37,-56,97,708,-214,-216],[-59,-49,90,-40,4,-19,-19,-77],[150,-80,-253,60,-465,82,471,-478],[-6,-156,-22,-17,87,56,-31,-67],[-68,15,-96,96,-201,178,-51,45],[52,78,32,-117,182,-15,8,14],[-31,81,-23,43,-83,-29,-27,2]])*1e-2
P0=np.array([[145,568,-74,-41,314,-606,349,208],[-78,686,-242,171,213,-32,-88,62],[-112,60,-337,169,-56,11,183,2],[9,57,421,5,360,-1017,169,175],[-768,-140,-4,327,361,-3653,1492,184],[-348,-1473,451,-311,-498,-483,592,41],[-489,340,336,-111,140,-1867,991,199],[-96,316,430,31,185,-611,65,8]])*1e-3
A1=np.array([[144,140,-62,-230,404,324,407,347],[-89,-281,-142,49,-333,-265,-371,96],[105,1,110,114,237,145,243,-82],[199,-601,207,963,-197,-144,-496,24],[42,98,-243,166,-1115,-599,-685,-128],[177,-163,344,641,639,338,432,-102],[-131,-185,694,880,480,286,107,549],[308,-1534,957,2960,898,189,-11,-410]])*1e-3
M=np.array([[368,73,-136,-78,-32,8],[-138,112,18,-31,-56,-81],[-1582,1260,163,-151,-195,-179],[-1277,1648,-2,-329,-338,-284],[-410,251,53,-66,-135,-208],[-215,34,47,15,-4,-22],[-380,200,55,-9,-26,-35],[162,-87,-28,-6,-7,-16]])*1e-2
WU=np.array([[-2297,25,674,1180,1843,2858],[95,478,-211,-121,-44,106],[548,-807,-66,125,95,17],[1929,809,-940,-871,-702,-661],[1419,-2849,-142,84,-280,-1004],[1377,-581,-203,-343,-543,-818],[1968,-837,-159,389,738,1185],[4921,3271,-1272,-2573,-3301,-4238]])*1e-3

def model(x,iv):
    t=[iv('t%d'%p,1.*(x[:,p][:,None]==np.arange(6))) for p in range(6)]
    E=np.stack([t[p]@WE+WP[p] for p in range(6)],1)
    s=E@A0@E.transpose(0,2,1)
    a=np.exp(s-s.max(2,keepdims=True));a/=a.sum(2,keepdims=True)
    a=iv('pat',a.reshape(len(x),-1)).reshape(len(x),6,6)
    r=E+np.einsum('bpj,bjd->bpd',a,E@P0)
    T=np.einsum('bd,bjd->bj',r[:,5]@A1,r)
    b=np.exp(T-T.max(1,keepdims=True));b/=b.sum(1,keepdims=True)
    b=iv('a1',b)
    return iv('sc',r[:,5]@WU+np.einsum('bj,bjd->bd',b,r@M))
ALIGN={'t0':['embed'],'t1':['embed'],'t2':['embed'],'t3':['embed'],'t4':['embed'],'t5':['embed'],'pat':['attn0.pattern'],'a1':['attn1.pattern'],'sc':['resid1.mid']}
